.5,132,60},{132,132.5,59},{132.5,133,47},{133,133.5,45},{133.5,134,57},{134,134.5,55},{134.5,135,43},{135,135.5,42},{135.5,136,54},{136,136.5,52},{136.5,137,40},{137,137.5,38},{137.5,138,50},{138,138.5,49},{138.5,139,45},{139,139.5,50},{139.5,140,55},{140,140.5,57},{140.5,141,55},{141,141.5,57},{141.5,142,45},{142,144,38}}},
